def solve(T):
    h,w=len(T),len(T[0])
    cnt=Counter(v for r in T for v in r); most=cnt.most_common(1)[0][0]
    # line: full row or col of single non-bg color
    L=None; axis=None
    for j in range(w):
        if len(set(T[i][j] for i in range(h)))==1:
            v=T[0][j]
            if v!=most: L=v; axis='v'; break
    else:
        for i in range(h):
            if len(set(T[i]))==1:
                v=T[i][0]
                if v!=most: L=v; axis='h'; break
    objs=set(range(10))-({most,L})
    o=max(objs,key=lambda v: sum(row.count(v) for row in T))
    out=[r[:] for r in T]
    cells=[(i,j) for i in range(h) for j in range(w) if T[i][j]==o]
    if axis=='v':  # vertical line at column lc; shift object horizontally to touch line
        lc=next(j for j in range(w) if all(T[i][j]==L for i in range(h)))
        cs=[j for _,j in cells]; rs=[i for i,_ in cells]
        cmin=min(cs); cmax=max(cs)
        if cmax < lc:          # object left of line -> shift right so its right edge touches lc
            shift=lc-cmax-1
            start = cmin+shift
        elif cmin > lc:         # right of line -> shift left so its left edge touches lc
            shift=lc-cmin-1
            start = cmin+shift
        else:                   # straddling line -> no shift? or keep as is; place 8 on one side only? demo3 doesn't straddle.
            shift=0; start=cmin
        for i in range(h):
            for j in range(cmin,cmax+1):
                if T[i][j]==o:
                    out[i][j+shift]=o
                else:
                    out[i][j]=8
        # fill remaining cells beyond the new far edge with 8
        if start + (cmax-cmin) > lc - 1 if False else True: pass
        # simple: from new far edge outward along the same direction as shift
        dir2 = shift
        if dir2>=0:   # shifted right
            for j in range(start+(cmax-cmin)+1, w):
                for i in range(rs[0],rs[-1]+1):
                    out[i][j]=8
        else:         # shifted left
            for j in range(start+(cmax-cmin)-1,-1,-1):
                for i in range(rs[0],rs[-1]+1):
                    out[i][j]=8
    else:           # horizontal line; shift vertically; object spans width? In demo1/2 objects span partial width but output fills row fully with 8 and object row fully with o.
        lr=next(i for i in range(h) if all(T[i][j]==L for j in range(w)))
        rs=[i for i,_ in cells]; cs=[j for _,j in cells]
        rmin=min(rs); rmax=max(rs)
        if rmax < lr:
            shift=lr-rmax-1; start=rmin+shift
        elif rmin > lr:
            shift=lr-rmin-1; start=rmin+shift
        else: shift=0;start=rmin
        for i in range(rmin,rmax+1):
            for j in range(w):
                out[i+shift][j]=8
        # restore object
        for i,j in cells: out[i+shift][j]=o
        # fill rest of object's row with 8
        for j in range(min(cs)+abs(shift), max(cs)+abs(shift)+1):
            out[start][j]=8 if out[start][j]!=o else o
        out[start]=[8]*w
    return out

