def solve(T):
    h,w=len(T),len(T[0])
    from collections import Counter
    cnt=Counter(v for r in T for v in r); most=cnt.most_common(1)[0][0]
    # find line (full row or col, non-bg) and its color
    L=None;axis=None
    for j in range(w):
        if len(set(T[i][j] for i in range(h)))==1 and T[0][j]!=most:
            L=T[0][j];axis='v';break
    else:
        for i in range(h):
            if len(set(T[i]))==1 and T[i][0]!=most:
                L=T[i][0];axis='h';break
    objs=set(range(10))-({most,L})
    o=max(objs,key=lambda v:sum(T[r].count(v) for r in range(h)))
    cells=[(i,j) for i in range(h) for j in range(w) if T[i][j]==o]
    out=[r[:] for r in T]
    if axis=='v':
        lc=next(j for j in range(w) if all(T[i][j]==L for i in range(h)))
        rs=[i for i,_ in cells]; cs=[j for _,j in cells]
        # 8-col at R; object centered between lc and R -> R = 2*obj_center - lc
        oc=(min(rs)+max(rs))/2.0
        R=int(round(2*oc-lc))
        # object row stays; shift horizontally so object center == (lc+R)/2
        target=(lc+R)/2.0
        cc=(min(cs)+max(cs))/2.0
        shift=int(round(target-cc))
        rmin=min(rs);rmax=max(rs)
        for i in range(rmin,rmax+1):
            for j in range(min(cs),max(cs)+1):
                out[i][j+shift]=T[i][j+shift] if T[i][j+shift]==o else (o if T[i][j+shift]==o else 8)
                pass
        for i in range(rmin,rmax+1):
            for j in range(min(cs)+shift,max(cs)+shift+1):
                out[i][j]=o
        for i in range(rmin,rmax+1):
            for j in range(R+1,w):
                out[i][j]=8
        # clear original
        for i in range(rmin,rmax+1):
            for j in range(min(cs),max(cs)+1):
                if T[i][j]==o and not (min(cs)+shift<=j<=max(cs)+shift):
                    out[i][j]=0
    else:
        lr=next(i for i in range(h) if all(T[i][j]==L for j in range(w)))
        rs=[i for i,_ in cells]; cs=[j for _,j in cells]
        oc=(min(rs)+max(rs))/2.0
        C=int(round(2*oc-lr))
        tr=(lr+C)/2.0
        rc=(min(cs)+max(cs))/2.0
        shift=int(round(tr-rc))
        rmin=min(rs);rmax=max(rs)
        for i,j in cells:
            out[i+shift][j]=o
        # clear originals
        for i in range(rmin,rmax+1):
            for j in range(min(cs),max(cs)+1):
                if T[i][j]==o and not (rmin+shift<=i<=rmax+shift):
                    out[i][j]=0
        for i in range(C+1,h):
            for j in range(w):
                out[i][j]=8
    return out
